{ "facts": [
  {
    "text": "Gareth Lloyd is the care assessor from the council.",
    "cites": [1],
    "section": "Background and presenting situation"
  },
  {
    "text": "Karen Wells is the daughter of Doreen Abbott.",
    "cites": [1, 2],
