      "cites": [20],
      "section": "Client's account"
    },
    {
      "text": "Council tax arrears have triggered a bailiff letter.",
      "cites": [22],
      "section": "Client's account"
    },
    {
      "text": "Lee has a credit card debt of approximately £2,000.",
      "cites": [22],
      "section": "Client's account"
    },
    {
      "text": "Electricity is now on a meter.",
      "cites": [22],
      "section": "Client's account"
