    {
      "text": "Lee has no support from family or friends for debt issues.",
      "cites": [24],
      "section": "Client's account"
    },
    {
      "text": "Lee stopped opening accounts or managing finances after losing his job.",
      "cites": [24],
      "section": "Client's account"
